type Category = {
  slug: string; title: string; cluster: string; answer: string; note: string;
  criteria: {title:string;body:string}[]; faqs:{q:string;a:string}[];
  workflowSlugs:string[]; products:ElectricianCandidate[];
  sections:{heading:string;body:string}[];
};
const fp = 'https://www.fieldpiece.com/product/';
function tool(id:string,brand:string,model:string,role:string,sourceUrl:string,fit:string,limit:string,features:[string,string][],why:string):ElectricianCandidate {
  return candidate(id,brand,model,role,sourceUrl,fit,limit,why,
    `${role}: ${features[0][1]}. ${limit} Compare this configuration with the alternatives below and price the accessories needed for your actual jobs.`,
    features.slice(0,3).map(([label,value])=>`${label}: ${value}`),[limit,'Confirm the seller, package and current manufacturer instructions'],features);
}
const f = (id:string,model:string,role:string,path:string,fit:string,limit:string,features:[string,string][],why:string) => tool(`fieldpiece-${id}`,'Fieldpiece',model,role,fp+path,fit,limit,features,why);
function group(slug:string,title:string,cluster:string,answer:string,note:string,criteria:[string,string][],faqs:[string,string][],jobs:string[],products:ElectricianCandidate[],sections:[string,string][]):Category {
  return {slug,title,cluster,answer,note,criteria:criteria.map(([title,body])=>({title,body})),faqs:faqs.map(([q,a])=>({q,a})),workflowSlugs:jobs,products,sections:sections.map(([heading,body])=>({heading,body}))};
}
