const affiliate=(p:ElectricianCandidate)=>`https://www.amazon.com/s?k=${encodeURIComponent(`${p.brand} ${p.model}`)}&tag=robbieom0e-20`;
export const hvacCatalogGuides:Guide[]=hvacCategories.map(c=>({trade:'hvac',tradeName:'HVAC Technicians',slug:c.slug,title:c.title,cluster:c.cluster,keyword:c.slug.replace(/-/g,' '),meta:`${c.title.split(':')[0]}: compare ${c.products.map(p=>p.model.split(' ')[0]).join(', ')} by application, configuration and limitations.`,workflowSlugs:c.workflowSlugs,products:c.products.map((p,i)=>({brand:p.brand,model:p.model,role:p.role,productId:p.id,assessment:p.assessment,reviewSlug:i===0?`hvac-${p.id}-review`:undefined,url:affiliate(p)}))}));
export function manifoldProducts(){return hvacManifoldAdditions.map(p=>({brand:p.brand,model:p.model,role:p.role,productId:p.id,assessment:p.assessment,reviewSlug:`${p.id}-review`,url:affiliate(p)}));}
const review=(p:ElectricianCandidate,slug:string,guideSlug:string,guideTitle:string,sections:Category['sections'],faqs:Category['faqs']):ProductReview=>({slug,trade:'hvac',tradeName:'HVAC Technicians',guideSlug,guideTitle,brand:p.brand,model:p.model,role:p.role,title:`${p.brand} ${p.model} Review: HVAC Job Fit and Alternatives`,meta:`${p.brand} ${p.model.split(' ')[0]} HVAC buying assessment: documented features, job fit, package checks and limitations. Research-based review.`,amazonUrl:affiliate(p),...p.assessment,sections,faqs:[...faqs,{q:'Was this tool independently tested?',a:'No. This is a research-based buying assessment using manufacturer documentation, not a claim of hands-on testing or measured comparative performance.'}]});
export const hvacCatalogReviews:ProductReview[]=[...hvacCategories.map(c=>review(c.products[0],`hvac-${c.products[0].id}-review`,c.slug,c.title,c.sections,c.faqs)),...hvacManifoldAdditions.map(p=>review(p,`${p.id}-review`,'best-digital-manifolds-for-hvac','Best Digital Manifolds for HVAC',[
  {heading:'Current model versus the preserved older review',body:`${p.model} is listed in Fieldpiece’s current manifold range. The original SM480V route is preserved for an older-generation comparison. Match the exact model rather than transferring specifications between the two generations.`},
  {heading:'Buy the connection arrangement you need',body:'Compare three and four ports by the evacuation and service setup you actually use. Temperature probes, hoses and other accessories still need checking in the complete offer.'},
  {heading:'Keep the documented application with the readings',body:'A refrigerant list, pressure rating and instrument calculation do not authorize a service procedure. Use the actual equipment instructions, appropriate qualified-work controls and required verification.'},
],[{q:'Is this the same tool as SM480V?',a:'No. This is a different current-generation model. The older product retains its own page and specifications.'}]))];
